//! Validation combinators for composing validations

use crate::prelude::*;
use crate::errors::{RodValidateError, RodValidateErrorList};
use crate::{RodFieldMeta, RodMetadata};
use std::time::Instant;

/// A trait for types that can be validated with combinators
///
/// Note: this trait intentionally does not provide a `validate_all` method,
/// because `RodValidate::validate_all` (generated by the derive macro) already
/// provides that functionality with a richer error type
/// (`RodValidateErrorList`).
pub trait RodValidateExt: RodValidate + Sized {
    /// Validate with any of the validations, returning success if at least one passes
    fn validate_any<F>(&self, validators: &[F]) -> Result<(), RodValidateError>
    where
        F: Fn(&Self) -> Result<(), RodValidateError>,
    {
        let mut last_error = None;
        for validator in validators {
            match validator(self) {
                Ok(()) => return Ok(()),
                Err(e) => last_error = Some(e),
            }
        }
        Err(last_error.unwrap_or_else(|| RodValidateError::CheckFailed("No validators provided")))
    }
    
    /// Validate with one of the validations, returning success if exactly one passes
    fn validate_one<F>(&self, validators: &[F]) -> Result<(), RodValidateError>
    where
        F: Fn(&Self) -> Result<(), RodValidateError>,
    {
        let mut success_count = 0;
        let mut last_error = None;
        for validator in validators {
            match validator(self) {
                Ok(()) => success_count += 1,
                Err(e) => last_error = Some(e),
            }
        }
        if success_count == 1 {
            Ok(())
        } else if success_count == 0 {
            Err(last_error.unwrap_or_else(|| RodValidateError::CheckFailed("No validators provided")))
        } else {
            Err(RodValidateError::CheckFailed("Multiple validators passed, expected exactly one"))
        }
    }
}

impl<T: RodValidate> RodValidateExt for T {}

/// A builder for conditional validation
pub struct ConditionalValidator<T> {
    value: T,
    condition: bool,
}

impl<T: RodValidate> ConditionalValidator<T> {
    /// Create a new conditional validator
    pub fn new(value: T, condition: bool) -> Self {
        Self { value, condition }
    }
    
    /// Validate if condition is true
    pub fn validate_if_valid(self) -> Result<(), RodValidateError> {
        if self.condition {
            self.value.validate()
        } else {
            Ok(())
        }
    }
    
    /// Validate if condition is false
    pub fn validate_if_invalid(self) -> Result<(), RodValidateError> {
        if !self.condition {
            self.value.validate()
        } else {
            Ok(())
        }
    }
}

/// A builder for cross-field validation
pub struct CrossFieldValidator<T> {
    value: T,
}

impl<T: RodValidate> CrossFieldValidator<T> {
    /// Create a new cross-field validator
    pub fn new(value: T) -> Self {
        Self { value }
    }
    
    /// Validate with a cross-field check
    pub fn validate_with<F, E>(self, check: F) -> Result<(), RodValidateError>
    where
        F: Fn(&T) -> Result<(), E>,
        E: Into<RodValidateError>,
    {
        check(&self.value).map_err(Into::into)
    }
}

/// A helper for group-based validation.
///
/// Works with fields tagged `#[rod(group = "name")]` (supported by the
/// `#[derive(RodValidate)]` macro). Fields without a group are always
/// validated, regardless of the requested group.
pub struct ValidationGroup<T> {
    value: T,
}

impl<T: RodValidate> ValidationGroup<T> {
    /// Create a new validation group helper
    pub fn new(value: T) -> Self {
        Self { value }
    }

    /// Validate only the fields belonging to the given group
    /// (plus fields without a group).
    pub fn validate_group(self, group: &str) -> Result<(), RodValidateErrorList> {
        self.value.validate_group(group)
    }

    /// Validate every field, regardless of its group.
    pub fn validate_all_groups(self) -> Result<(), RodValidateErrorList> {
        self.value.validate_all_groups()
    }
}

/// A builder for validation pipeline
pub struct ValidationPipeline<T> {
    value: T,
    errors: Vec<RodValidateError>,
}

impl<T: RodValidate> ValidationPipeline<T> {
    /// Create a new validation pipeline
    pub fn new(value: T) -> Self {
        Self { value, errors: Vec::new() }
    }
    
    /// Add a validation step
    pub fn step<F>(mut self, step: F) -> Self
    where
        F: Fn(&T) -> Result<(), RodValidateError>,
    {
        if let Err(e) = step(&self.value) {
            self.errors.push(e);
        }
        self
    }
    
    /// Add a validation step that collects all errors
    pub fn step_all<F>(mut self, step: F) -> Self
    where
        F: Fn(&T) -> Result<(), RodValidateErrorList>,
    {
        if let Err(errors) = step(&self.value) {
            self.errors.extend(errors);
        }
        self
    }
    
    /// Get the final result
    pub fn result(self) -> Result<(), RodValidateError> {
        if self.errors.is_empty() {
            Ok(())
        } else {
            Err(self.errors[0].clone())
        }
    }
    
    /// Get all errors
    pub fn all_errors(self) -> Vec<RodValidateError> {
        self.errors
    }
}

/// The result of a metric-instrumented validation run.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ValidationRun {
    /// Number of validated fields (each may perform multiple checks).
    pub checks: usize,
    /// Number of fields whose validation failed.
    pub failures: usize,
    /// Wall-clock duration of the validation run in milliseconds.
    pub duration_ms: u128,
}

/// Metrics around validation runs.
///
/// Implemented automatically for every `#[derive(RodValidate)]` type via the
/// derive-generated [`RodMetadata`] implementation.
pub trait ValidationMetrics: RodMetadata + RodValidate {
    /// The number of validated fields.
    fn validation_check_count() -> usize {
        Self::FIELDS.len()
    }

    /// Run `validate_all` while measuring duration and counting failures.
    fn validate_with_metrics(&self) -> ValidationRun {
        let start = Instant::now();
        let result = self.validate_all();
        let duration_ms = start.elapsed().as_millis();
        let failures = match &result {
            Err(errors) => errors.len(),
            Ok(()) => 0,
        };
        ValidationRun {
            checks: Self::FIELDS.len(),
            failures,
            duration_ms,
        }
    }
}

impl<T: RodMetadata + RodValidate> ValidationMetrics for T {}

/// Static field metadata for UI/form generation.
///
/// Implemented automatically for every `#[derive(RodValidate)]` type via the
/// derive-generated [`RodMetadata`] implementation.
pub trait ValidationMetadata: RodMetadata {
    /// Metadata of every validated field, in declaration order.
    fn fields(&self) -> &'static [RodFieldMeta] {
        Self::FIELDS
    }

    /// Names of all required fields.
    fn required_fields(&self) -> Vec<&'static str> {
        Self::FIELDS
            .iter()
            .filter(|f| f.required)
            .map(|f| f.name)
            .collect()
    }

    /// Names of all optional fields (fields with an `Option { ... }` rule).
    fn optional_fields(&self) -> Vec<&'static str> {
        Self::FIELDS
            .iter()
            .filter(|f| !f.required)
            .map(|f| f.name)
            .collect()
    }

    /// Metadata of the fields tagged with the given group.
    fn fields_in_group(group: &str) -> Vec<&'static RodFieldMeta> {
        Self::FIELDS
            .iter()
            .filter(|f| f.group == Some(group))
            .collect()
    }
}

impl<T: RodMetadata> ValidationMetadata for T {}

/// Async counterpart of [`RodValidate`].
///
/// Implemented automatically by `#[derive(RodValidate)]` (there is no blanket
/// impl, because the derive must be able to override
/// [`AsyncValidator::run_async_checks`] for types declaring async checks).
/// Two levels:
///
/// 1. **Synchronous rules**: by default `run_async_checks` runs no checks, so
///    `validate_async` collects the same errors as `validate_all`.
/// 2. **Async checks**: fields declaring
///    `#[rod(..., async_check = |x| future_of_bool)]` get a generated
///    `run_async_checks` override that awaits each closure (e.g. a database
///    lookup) and collects failures.
///
/// `validate_async` therefore validates *everything*: all synchronous rules
/// first, then every `async_check`, returning one combined error list.
/// Async-check closures must return `Send` futures; since checks run against
/// `&self`, the validated type is additionally required to be `Sync`.
pub trait AsyncValidator: RodValidate + Sync {
    /// Hook for the derive-generated `async_check` steps.
    ///
    /// Returns the errors produced by the type's async checks. The default
    /// implementation runs no checks; the derive overrides it only for types
    /// declaring at least one `async_check`.
    fn run_async_checks(
        &self,
    ) -> impl std::future::Future<Output = Vec<RodValidateError>> + Send {
        std::future::ready(Vec::new())
    }

    /// Validate the whole value asynchronously, collecting every error:
    /// all synchronous rules plus every `async_check`.
    fn validate_async(
        &self,
    ) -> impl std::future::Future<Output = Result<(), RodValidateErrorList>> + Send {
        async move {
            let mut errors = match self.validate_all() {
                Ok(()) => RodValidateErrorList::new(),
                Err(errors) => errors,
            };
            for error in self.run_async_checks().await {
                errors.push(error);
            }
            if errors.is_empty() {
                Ok(())
            } else {
                Err(errors)
            }
        }
    }
}

/// A trait for validation with different modes
pub trait ValidationMode {
    /// Validate in strict mode (fail on first error)
    fn validate_strict(&self) -> Result<(), RodValidateError>;
    
    /// Validate in warn mode (collect all errors but don't fail)
    fn validate_warn(&self) -> Result<(), RodValidateError>;
}

impl<T: RodValidate> ValidationMode for T {
    fn validate_strict(&self) -> Result<(), RodValidateError> {
        self.validate()
    }
    
    fn validate_warn(&self) -> Result<(), RodValidateError> {
        // In warn mode, we still return the first error but could collect all
        self.validate()
    }
}

/// A trait for generating JSON Schema from validation rules
#[cfg(feature = "serde")]
pub trait ToJsonSchema {
    /// Generate a JSON Schema from the validation rules
    fn to_json_schema() -> serde_json::Value;
}

/// A trait for validation testing utilities
pub trait ValidationTestUtils {
    /// Check if a value passes validation
    fn passes_validation(&self) -> bool;
    
    /// Check if a value fails validation
    fn fails_validation(&self) -> bool;
    
    /// Get the first validation error
    fn first_validation_error(&self) -> Option<RodValidateError>;
    
    /// Get all validation errors
    fn all_validation_errors(&self) -> Vec<RodValidateError>;
}

impl<T: RodValidate> ValidationTestUtils for T {
    fn passes_validation(&self) -> bool {
        self.validate().is_ok()
    }
    
    fn fails_validation(&self) -> bool {
        self.validate().is_err()
    }
    
    fn first_validation_error(&self) -> Option<RodValidateError> {
        self.validate().err()
    }
    
    fn all_validation_errors(&self) -> Vec<RodValidateError> {
        match self.validate_all() {
            Ok(()) => Vec::new(),
            Err(errors) => errors.iter().cloned().collect(),
        }
    }
}
